  foreach($products as $pi=>$d){[$name,$slug,$price,$cat,$col,$image,$desc,$colors]=$d;$p=Product::updateOrCreate(['slug'=>$slug],['name'=>$name,'description'=>$desc,'status'=>ProductStatus::Active,'base_price'=>$price,'seo_title'=>$name.' — RAOZA','seo_description'=>$desc,'indexable'=>true,'published_at'=>now()->subHours(12-$pi)]);$p->categories()->sync([$cat->id=>['position'=>$pi]]);$p->collections()->sync([$col->id=>['position'=>$pi]]);ProductImage::updateOrCreate(['product_id'=>$p->id,'path'=>$image],['variant_id'=>null,'alt_text'=>$name.' demo placeholder','position'=>0,'width'=>1200,'height'=>1500]);
