   $n=0;foreach($sizes as $sv=>$sval)foreach($colorVals as $cv=>$cval){$ids=[$sval->id,$cval->id];$sku='RZ-'.strtoupper(substr(preg_replace('/[^a-z0-9]/i','',$slug),0,6)).'-'.$sv.'-'.strtoupper(substr($cv,0,3));$v=ProductVariant::updateOrCreate(['sku'=>$sku],['product_id'=>$p->id,'price_override'=>null,'status'=>VariantStatus::Active,'option_signature'=>VariantSignature::fromOptionValueIds($ids)]);$v->optionValues()->sync($ids);$qty=($pi===5&&$sv==='XL')?0:(($pi===5&&$sv==='L')?2:8+(($pi+$n)%7));$inv=Inventory::updateOrCreate(['variant_id'=>$v->id],['quantity_on_hand'=>$qty,'quantity_reserved'=>0]);if(!InventoryMovement::where('variant_id',$v->id)->where('reference_type','demo_seed')->exists())InventoryMovement::create(['variant_id'=>$v->id,'type'=>InventoryMovementType::StockReceived,'quantity'=>$qty,'reference_type'=>'demo_seed','reference_id'=>'initial','note'=>'Local demo opening stock','created_at'=>now()]);$n++;}
